describe('ms_pointer_modifier sub-factories', () => {
	it('msRestrictModifier builds the parent', () => {
		const node = ir.msPointerModifier.msRestrictModifier();
		expect(node.$type).toBe(TSKindId.MsPointerModifier);
		const seated = (node as any).content();
		expect(seated?.$text?.() ?? seated).toBe(TSKindId.MsRestrictModifier);
		expect(node.$render!().length).toBeGreaterThan(0);
	});
	it('msUnsignedPtrModifier builds the parent', () => {
		const node = ir.msPointerModifier.msUnsignedPtrModifier();
		expect(node.$type).toBe(TSKindId.MsPointerModifier);
		const seated = (node as any).content();
		expect(seated?.$text?.() ?? seated).toBe(TSKindId.MsUnsignedPtrModifier);
		expect(node.$render!().length).toBeGreaterThan(0);
	});
	it('msSignedPtrModifier builds the parent', () => {
		const node = ir.msPointerModifier.msSignedPtrModifier();
		expect(node.$type).toBe(TSKindId.MsPointerModifier);
		const seated = (node as any).content();
		expect(seated?.$text?.() ?? seated).toBe(TSKindId.MsSignedPtrModifier);
		expect(node.$render!().length).toBeGreaterThan(0);
	});
});

